From 06b86e000fdf22a22b51674a9f0a42acb7a2dcaa Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 20:07:51 +0100
Subject: [PATCH] wallpapers/image: add option to span the image across all
 screens

Every screen always showed the whole wallpaper image, so a wide picture
made for several monitors was repeated on each of them. Add a "Span
across all screens" option that lays the image over the whole desktop.

BUG: 393781
---
 .../imagepackage/contents/config/main.xml     |  4 +++
 .../image/imagepackage/contents/ui/config.qml | 12 ++++++++
 .../image/imagepackage/contents/ui/main.qml   | 28 +++++++++++++++++--
 3 files changed, 42 insertions(+), 2 deletions(-)

diff --git a/wallpapers/image/imagepackage/contents/config/main.xml b/wallpapers/image/imagepackage/contents/config/main.xml
index 1c47869b78..1b51ec7806 100644
--- a/wallpapers/image/imagepackage/contents/config/main.xml
+++ b/wallpapers/image/imagepackage/contents/config/main.xml
@@ -36,6 +36,10 @@
       <label>Sizing, cropping and positioning of the wallpaper image</label>
       <default>2</default>
     </entry>
+    <entry name="SpanScreens" type="bool">
+      <label>Span the wallpaper image across all screens</label>
+      <default>false</default>
+    </entry>
     <entry name="SlideshowFoldersFirst" type="bool">
       <label>Display folders first when on slideshow</label>
       <default>false</default>
diff --git a/wallpapers/image/imagepackage/contents/ui/config.qml b/wallpapers/image/imagepackage/contents/ui/config.qml
index 533cc1fff8..7129918e37 100644
--- a/wallpapers/image/imagepackage/contents/ui/config.qml
+++ b/wallpapers/image/imagepackage/contents/ui/config.qml
@@ -50,6 +50,8 @@ ColumnLayout {
     property int cfg_DynamicModeDefault: 0
     property bool cfg_ForceImageAnimation: false
     property bool cfg_ForceImageAnimationDefault: false
+    property alias cfg_SpanScreens: spanScreensCheckBox.checked
+    property bool cfg_SpanScreensDefault: false

     signal configurationChanged()
     /**
@@ -191,6 +193,16 @@ ColumnLayout {
             }
         }

+        QtControls2.CheckBox {
+            id: spanScreensCheckBox
+            visible: root.configDialog.currentWallpaper === "org.kde.image" && Qt.application.screens.length > 1
+            text: i18ndc("plasma_wallpaper_org.kde.image", "@option:check", "Span across all screens")
+
+            KCM.SettingHighlighter {
+                highlight: root.cfg_SpanScreensDefault != root.cfg_SpanScreens
+            }
+        }
+
         QtControls2.ButtonGroup { id: dayNightModeGroup }


diff --git a/wallpapers/image/imagepackage/contents/ui/main.qml b/wallpapers/image/imagepackage/contents/ui/main.qml
index 14aac831f8..513e16adc3 100644
--- a/wallpapers/image/imagepackage/contents/ui/main.qml
+++ b/wallpapers/image/imagepackage/contents/ui/main.qml
@@ -30,6 +30,27 @@ WallpaperItem {
         root.configuration.writeConfig();
     }

+    // The whole desktop, relative to this screen, when the image spans all screens
+    readonly property rect spanGeometry: {
+        if (root.pluginName !== "org.kde.image" || !root.configuration.SpanScreens) {
+            return Qt.rect(0, 0, root.width, root.height);
+        }
+        const screens = Qt.application.screens;
+        let left = Screen.virtualX;
+        let top = Screen.virtualY;
+        let right = Screen.virtualX + root.width;
+        let bottom = Screen.virtualY + root.height;
+        for (const screen of screens) {
+            left = Math.min(left, screen.virtualX);
+            top = Math.min(top, screen.virtualY);
+            right = Math.max(right, screen.virtualX + screen.width);
+            bottom = Math.max(bottom, screen.virtualY + screen.height);
+        }
+        return Qt.rect(left - Screen.virtualX, top - Screen.virtualY, right - left, bottom - top);
+    }
+
+    clip: true
+
     contextualActions: root.pluginName === "org.kde.slideshow" ? [openWallpaperAction, imageWallpaper.nextSlideAction] : []

     PlasmaCore.Action {
@@ -61,7 +82,10 @@ WallpaperItem {

     ImageStackView {
         id: imageView
-        anchors.fill: parent
+        x: root.spanGeometry.x
+        y: root.spanGeometry.y
+        width: root.spanGeometry.width
+        height: root.spanGeometry.height

         fillMode: root.configuration.FillMode
         configColor: root.configuration.Color
@@ -77,7 +101,7 @@ WallpaperItem {
             }
             return root.configuration.Image;
         }
-        sourceSize: Qt.size(root.width * Screen.devicePixelRatio, root.height * Screen.devicePixelRatio)
+        sourceSize: Qt.size(width * Screen.devicePixelRatio, height * Screen.devicePixelRatio)
         wallpaperInterface: root

         Wallpaper.ImageBackend {
-- 
